# Geographic operating scopes: one canonical taxonomy, two jurisdictional views.
GEOGRAPHIC_SCOPES = ({"scope_id": "bharat", "scope_name": "Bharat", "description": "India-focused jurisdiction, market and operating context."}, {"scope_id": "global_world", "scope_name": "Global World", "description": "Cross-border and international market context."})
def list_scoped_domains():
    """Return Bharat and Global World views for every canonical domain."""
    return [dict(domain, scope_id=scope["scope_id"], scope_name=scope["scope_name"], scoped_domain_id=f'{scope["scope_id"]}_{domain["domain_id"]}', scoped_name=f'{scope["scope_name"]} {domain["name"]}') for domain in list_domains() for scope in GEOGRAPHIC_SCOPES]
def get_scoped_domain(key):
    normalized = key.strip().casefold()
    return next((item for item in list_scoped_domains() if item["scoped_domain_id"] == normalized), None)
def list_geographic_scopes():
    return [dict(scope) for scope in GEOGRAPHIC_SCOPES]
